{"implementation":"import math


def solve(case):
    def require_number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            raise ValueError(f"invalid {name}")
        return float(value)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    threshold = require_number(case["threshold"], "threshold")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    accepted_call_ids = []
    diagnostics = []
    validated = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("call must be an object")
        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        loss_without = require_number(call["loss_without_call"], "loss_without_call")
        loss_with = require_number(call["loss_with_call"], "loss_with_call")
        prediction_tokens = call["prediction_tokens"]
        if isinstance(prediction_tokens, bool) or not isinstance(prediction_tokens, int) or prediction_tokens < 0:
            raise ValueError("prediction_tokens must be a nonnegative integer")
        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be boolean")
        validated.append((call_id, loss_without, loss_with, prediction_tokens, parseable))

    for call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        weight = 1.0 / max(1, prediction_tokens)
        normalized_gain = (loss_without * weight) - (loss_with * weight)
        rounded_gain = round(normalized_gain, 6)
        accepted = parseable and loss_with < loss_without and normalized_gain >= threshold
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": rounded_gain,
        })
        if accepted:
            accepted_call_ids.append(call_id)

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }"}
